/*
 * Bundles a plugin script with the CommonJS modules it requires into one file,
 * since the SDK copies the plugin script into the pbw as it is.
 *
 * Usage: node tools/bundle_plugin.js <entry> <output>
 *
 * The output is written only when its content changes, so that waf does not
 * repackage the app for nothing.
 */

var fs = require('fs');
var path = require('path');

var REQUIRE = /\brequire\('([^']+)'\)/g;

/** Path of module `name` required from `from`, both relative to `root`. */
function resolve(from, name) {
  var resolved = path.posix.normalize(path.posix.join(path.posix.dirname(from), name));
  return /\.js$/.test(resolved) ? resolved : resolved + '.js';
}

/** The bundle of `entry`, a path relative to `root`, as a string. */
function bundle(root, entry) {
  var modules = [];
  var seen = {};
  (function add(file) {
    if (seen[file]) return;
    seen[file] = true;
    var source = fs.readFileSync(path.join(root, file), 'utf8');
    var deps = {};
    var match;
    REQUIRE.lastIndex = 0;
    while ((match = REQUIRE.exec(source)) !== null) deps[match[1]] = resolve(file, match[1]);
    modules.push({ file: file, source: source, deps: deps });
    Object.keys(deps).forEach(function (name) { add(deps[name]); });
  }(entry));

  var out = [
    '// Generated by tools/bundle_plugin.js from ' + entry + ' and the modules it',
    '// requires: edit those, not this file.',
    '(function () {',
    '  var modules = {',
  ];
  modules.forEach(function (m) {
    out.push('    ' + JSON.stringify(m.file) + ': [function (module, exports, require) {');
    out.push(m.source.replace(/\s+$/, ''));
    out.push('    }, ' + JSON.stringify(m.deps) + '],');
  });
  out.push(
    '  };',
    '  var loaded = {};',
    '  function load(file) {',
    '    if (!loaded[file]) {',
    '      var module = loaded[file] = { exports: {} };',
    '      modules[file][0](module, module.exports, function (name) {',
    '        return load(modules[file][1][name]);',
    '      });',
    '    }',
    '    return loaded[file].exports;',
    '  }',
    '  load(' + JSON.stringify(entry) + ');',
    '}());',
    '');
  return out.join('\n');
}

module.exports = { bundle: bundle };

if (require.main === module) {
  var root = process.cwd();
  var output = path.join(root, process.argv[3]);
  var text = bundle(root, process.argv[2]);
  var current = fs.existsSync(output) ? fs.readFileSync(output, 'utf8') : null;
  if (current !== text) fs.writeFileSync(output, text);
}
